from . import P

PACKS=[
P(3,"Une nouvelle collègue", """Bonjour ! Je m’appelle Mina. J’ai vingt-huit ans et je suis dessinatrice. Je viens de Belgique, mais j’habite maintenant à Lyon. Je parle français et anglais. Au bureau, mon collègue s’appelle Sami. Il est comptable. Nous travaillons dans une petite équipe. Le matin, nous prenons un café ensemble. Le vendredi, nous déjeunons au parc quand il fait beau.""",
"Mina introduces herself and her colleague, their jobs and their shared routine.",[
("Quel est le métier de Mina ?","Dessinatrice","Comptable","Professeure","je suis dessinatrice"),
("Où habite-t-elle maintenant ?","À Lyon","En Belgique","À Paris","j’habite maintenant à Lyon"),
("Que font les collègues le vendredi ?","Ils déjeunent au parc","Ils suivent un cours","Ils restent toujours au bureau","nous déjeunons au parc")],
[("Sami","Bonjour, vous êtes la nouvelle collègue ?"),("Mina","Oui, je m’appelle Mina. Et vous ?"),("Sami","Moi, c’est Sami. Vous venez de Lyon ?"),("Mina","Non, je viens de Belgique. J’habite ici depuis peu."),("Sami","Bienvenue ! Nous pouvons nous tutoyer, si vous voulez."),("Mina","Avec plaisir. Tu travailles dans quel service ?")],
[("Que propose Sami ?","De se tutoyer","De changer de bureau","De partir en Belgique","nous pouvons nous tutoyer"),
("Mina vient-elle de Lyon ?","Non, de Belgique","Oui, de Lyon","Elle ne le dit pas","je viens de Belgique")],
[("je m’appelle","my name is"),("je viens de","I come from"),("une petite équipe","a small team")],
"Write a short introduction for a new classmate: your name, a fictional age, city, languages and one interest.",
"Introduce yourself to a new colleague. Ask their name, job and where they live; choose tu or vous appropriately.",
"Vous can address one person politely or several people. Nous is not simply a formal replacement for on. A profession after être normally has no article in a simple identification: je suis dessinatrice."),

P(4,"Dans mon sac", """Voici mon sac pour le cours. Il y a un cahier bleu, une trousse et deux livres. Dans la trousse, j’ai un stylo noir et une gomme. La gomme est petite. Le cahier est neuf. J’ai aussi une bouteille d’eau. Mon téléphone est dans la poche du sac. À la maison, le sac reste près de la porte.""",
"A learner describes the objects in a school bag and their locations.",[
("Combien de livres y a-t-il ?","Deux","Un","Trois","deux livres"),
("Où est le téléphone ?","Dans la poche du sac","Sur la table","Dans la trousse","dans la poche du sac"),
("Quel objet est neuf ?","Le cahier","La gomme","Le sac","Le cahier est neuf")],
[("Lina","Tu as une gomme ?"),("Noé","Oui, elle est dans ma trousse."),("Lina","Je peux la prendre un instant ?"),("Noé","Bien sûr. Tu veux aussi un stylo ?"),("Lina","Non merci, j’ai mon stylo."),("Noé","D’accord. Voici la gomme.")],
[("Que demande Lina ?","Une gomme","Un cahier","Une bouteille","Tu as une gomme"),
("A-t-elle besoin d’un stylo ?","Non","Oui, de deux stylos","Elle ne sait pas","j’ai mon stylo")],
[("il y a","there is / there are"),("dans la trousse","in the pencil case"),("près de la porte","near the door")],
"Describe five objects in your study bag. Use un/une, le/la and at least one plural noun.",
"Ask a classmate to lend you two classroom objects. Say where they are and thank the classmate.",
"Learn a noun with its article. L’ hides gender before a vowel or mute h; it does not mean that the noun has no gender. Il y a stays unchanged with plural objects."),

P(5,"Après le travail", """Le mardi, Hugo termine son travail à dix-sept heures. Il rentre à pied et écoute de la musique. Sa voisine Clara étudie le français. Ils parlent souvent dans la cour. Clara pose des questions et Hugo explique les mots nouveaux. Ensuite, ils préparent un repas simple. Ils ne regardent pas la télévision : ils préfèrent discuter. Le cours de Clara commence le lendemain matin.""",
"Two neighbours practise French and spend an evening together.",[
("Comment Hugo rentre-t-il ?","À pied","En métro","En voiture","Il rentre à pied"),
("Qui étudie le français ?","Clara","Hugo","Leur professeur","Clara étudie le français"),
("Que préfèrent-ils faire ?","Discuter","Regarder la télévision","Aller au cinéma","ils préfèrent discuter")],
[("Clara","Tu travailles demain ?"),("Hugo","Oui, mais je termine à cinq heures."),("Clara","Nous préparons le dîner ensemble ?"),("Hugo","Bonne idée. Tu apportes les légumes ?"),("Clara","Oui, et tu prépares le riz."),("Hugo","D’accord. Nous mangeons à six heures.")],
[("Qui apporte les légumes ?","Clara","Hugo","La voisine de Hugo","Tu apportes les légumes"),
("À quelle heure mangent-ils ?","À six heures","À cinq heures","À sept heures","Nous mangeons à six heures")],
[("à pied","on foot"),("les mots nouveaux","the new words"),("un repas simple","a simple meal")],
"Describe an evening using five present-tense verbs. Include one sentence with nous and one with ils or elles.",
"Plan an evening meal with a partner. Agree who brings the food, who cooks and when you eat.",
"An infinitive names the verb; the finite form matches the subject. Most -er verbs are regular, but spelling can change to preserve pronunciation: nous mangeons. Written endings may sound identical."),

P(6,"Un cours de cuisine", """Le centre du quartier propose un cours de cuisine samedi. Le cours commence à dix heures et se termine à midi. Il coûte quinze euros. Les participants préparent une soupe et un dessert. Il faut apporter une boîte pour emporter le repas. Le centre fournit les ingrédients. Pour réserver, on téléphone à l’accueil avant jeudi. Le cours est ouvert aux adultes débutants.""",
"An announcement gives practical information about a beginner cooking class.",[
("À qui le cours est-il destiné ?","Aux adultes débutants","Aux enfants seulement","Aux cuisiniers professionnels","aux adultes débutants"),
("Que faut-il apporter ?","Une boîte","Les ingrédients","Une soupe","apporter une boîte"),
("Quand faut-il réserver ?","Avant jeudi","Samedi à midi","Après le cours","avant jeudi")],
[("Client","Bonjour, où se passe le cours ?"),("Accueil","Dans la cuisine du centre, au premier étage."),("Client","Comment est-ce que je réserve ?"),("Accueil","Vous pouvez réserver ici ou par téléphone."),("Client","Pourquoi faut-il une boîte ?"),("Accueil","Pour emporter votre repas après le cours.")],
[("Où est la cuisine ?","Au premier étage","Au rez-de-chaussée","Dans un restaurant","au premier étage"),
("À quoi sert la boîte ?","À emporter le repas","À payer le cours","À apporter des ingrédients","emporter votre repas")],
[("se termine à midi","finishes at noon"),("pour réserver","to book"),("avant jeudi","before Thursday")],
"Write four questions about a class: where, when, price and booking. Use at least two different question structures.",
"Telephone a community centre to ask about a class. Ask for missing details rather than reading a memorized list.",
"A question word identifies the missing information: où for place, quand for time, comment for method and pourquoi for reason. Do not combine est-ce que with subject–verb inversion in the same neutral question."),

P(7,"Une semaine bien organisée", """Nora suit un cours de français le lundi et le mercredi à dix-huit heures trente. Le cours dure une heure. Le vendredi, elle finit son travail à seize heures et fait les courses. Samedi, elle a rendez-vous avec son frère à onze heures devant la bibliothèque. Dimanche, elle reste chez elle. Elle prépare son agenda et téléphone à ses parents dans l’après-midi.""",
"Nora uses her weekly timetable to organize classes, shopping and family time.",[
("Quels jours Nora a-t-elle cours ?","Lundi et mercredi","Mardi et jeudi","Vendredi et samedi","le lundi et le mercredi"),
("Combien de temps dure le cours ?","Une heure","Trente minutes","Deux heures","Le cours dure une heure"),
("Où voit-elle son frère ?","Devant la bibliothèque","Au magasin","Chez ses parents","devant la bibliothèque")],
[("Nora","Notre rendez-vous est à dix heures ?"),("Frère","Non, à onze heures, samedi."),("Nora","À onze heures précises ?"),("Frère","Oui. Je dois partir à midi."),("Nora","D’accord, je note samedi à onze heures."),("Frère","Parfait. À samedi !")],
[("Quel jour est le rendez-vous ?","Samedi","Dimanche","Vendredi","samedi"),
("Pourquoi le frère veut-il être ponctuel ?","Il part à midi","Il a cours à onze heures","Il travaille toute la journée","Je dois partir à midi")],
[("dix-huit heures trente","six thirty p.m."),("une heure","one hour"),("dans l’après-midi","in the afternoon")],
"Write a timetable with three appointments. Distinguish the day, the starting time and the duration.",
"Confirm an appointment with a partner. Correct one misunderstood day or time and repeat the agreed details.",
"Use à for clock time and le for a regular weekday routine. Une heure is a duration; à une heure is a time. French dates and ordinary weekday names are lowercase."),

P(8,"Une photo de famille", """Sur cette photo, ma sœur est à gauche et mon frère est à droite. Notre mère est au milieu. Elle porte son manteau vert. Mon frère a deux enfants. Sa fille a six ans et son fils a neuf ans. Leur grand-père habite loin, mais il téléphone souvent. Ce soir, toute la famille prépare un repas pour son anniversaire. Chacun apporte quelque chose.""",
"A family photograph introduces relatives, possession and ages.",[
("Qui est au milieu ?","La mère","La sœur","Le grand-père","Notre mère est au milieu"),
("Quel âge a la fille ?","Six ans","Neuf ans","Dix ans","Sa fille a six ans"),
("Pourquoi prépare-t-on un repas ?","Pour l’anniversaire du grand-père","Pour un mariage","Pour un départ","pour son anniversaire")],
[("Amie","C’est ta sœur sur la photo ?"),("Léo","Oui. Et à droite, c’est mon frère."),("Amie","Ses enfants viennent ce soir ?"),("Léo","Oui, ils apportent un gâteau avec leurs parents."),("Amie","Et ton grand-père ?"),("Léo","Il vient aussi. C’est son anniversaire.")],
[("Qui apporte un gâteau ?","Les enfants et leurs parents","L’amie de Léo","Le grand-père seul","un gâteau avec leurs parents"),
("De qui est-ce l’anniversaire ?","Au grand-père","À la sœur","À Léo","ton grand-père")],
[("au milieu","in the middle"),("a six ans","is six years old"),("chacun apporte","each person brings")],
"Describe a real or fictional family photo. Use three possessive determiners and give two ages.",
"Ask about the people in a family photograph. Clarify who is related to whom without guessing their identities.",
"Mon/ma/mes agree with the possessed noun, not the owner. Son can mean his or her. Use avoir for age. Before a feminine noun beginning with a vowel, use mon amie, not ma amie."),

P(9,"Choisir une veste", """Lina cherche une veste pour le printemps. Dans le magasin, elle voit une petite veste rouge et une longue veste noire. La rouge est légère, mais ses poches sont petites. La noire est plus chaude. Lina préfère les vêtements simples. Elle essaie la veste noire devant un grand miroir. La taille est bonne. Elle demande le prix avant de prendre sa décision.""",
"A shopper compares two jackets using size, colour and practical details.",[
("Quelle veste est légère ?","La rouge","La noire","Les deux","La rouge est légère"),
("Quel détail est petit ?","Les poches de la veste rouge","Le miroir","La veste noire","ses poches sont petites"),
("Que fait Lina avant de décider ?","Elle demande le prix","Elle quitte le magasin","Elle achète les deux","Elle demande le prix")],
[("Lina","Cette veste existe en bleu ?"),("Vendeur","Oui, mais seulement en petite taille."),("Lina","Je cherche une taille moyenne."),("Vendeur","Alors, essayez la noire. Elle est disponible en taille moyenne."),("Lina","D’accord. Elle est légère ?"),("Vendeur","Elle est un peu plus chaude que la rouge.")],
[("Quelle taille veut Lina ?","Une taille moyenne","Une petite taille","Une grande taille","une taille moyenne"),
("Quelle veste propose le vendeur ?","La noire","La bleue","La rouge","essayez la noire")],
[("une petite veste","a small jacket"),("plus chaude","warmer"),("prendre sa décision","make her decision")],
"Describe two pieces of clothing. Include a colour, a size and one adjective before the noun.",
"Ask for a clothing item in a different colour or size. Explain which option you prefer and why.",
"Adjectives agree with the noun. Many common short adjectives often come before it; colours usually follow it. Do not treat adjective position as a universal rule independent of meaning."),

P(10,"Le dîner de vendredi", """Vendredi soir, nous invitons deux amis. Pour le dîner, nous préparons du riz, des légumes et une salade. Il reste de l’huile, mais il n’y a plus de pain. Je vais à la boulangerie. Mon ami ne mange pas de viande. Nous achetons donc aussi des lentilles. Pour le dessert, chacun prend un fruit. Nous aimons les repas simples et nous buvons de l’eau.""",
"Friends plan a simple meal, check supplies and accommodate a food preference.",[
("Que manque-t-il à la maison ?","Du pain","De l’huile","De l’eau","il n’y a plus de pain"),
("Pourquoi achètent-ils des lentilles ?","Un ami ne mange pas de viande","Ils détestent le riz","Il n’y a aucun légume","Mon ami ne mange pas de viande"),
("Que prennent-ils au dessert ?","Un fruit chacun","Un gâteau","Du fromage","chacun prend un fruit")],
[("Client","Bonjour, je voudrais deux petits pains, s’il vous plaît."),("Boulangère","Bien sûr. Autre chose ?"),("Client","Vous avez une tarte aux pommes ?"),("Boulangère","Oui, une grande tarte ou une part ?"),("Client","Une part seulement. Combien cela fait-il ?"),("Boulangère","Cela fait cinq euros au total.")],
[("Quelle quantité de tarte choisit le client ?","Une part","Une grande tarte","Deux tartes","Une part seulement"),
("Quel est le prix total ?","Cinq euros","Deux euros","Dix euros","cinq euros au total")],
[("il n’y a plus de pain","there is no bread left"),("ne mange pas de viande","does not eat meat"),("chacun prend un fruit","each person takes a piece of fruit")],
"Write a shopping list and a short meal plan. Use partitives, a counted quantity and one negative food preference.",
"Order food in a shop. Specify a quantity, ask the price and politely correct an unsuitable option.",
"Use partitives for an unspecified amount, but de after many quantity expressions and ordinary total negation. Definite articles express general preferences; preference verbs do not require a definite article in every possible context."),

P(11,"Trouver la médiathèque", """La médiathèque est près de la place du marché. Pour y aller depuis la gare, prenez la rue des Écoles. Continuez tout droit jusqu’au parc. Tournez à gauche après la pharmacie. La médiathèque est le bâtiment blanc, en face du parc. L’entrée est à côté du café. Le samedi, elle ouvre à neuf heures. Il y a un arrêt de bus devant la porte.""",
"Directions connect a station, a park and a public library.",[
("Après quel lieu faut-il tourner ?","La pharmacie","Le café","La gare","après la pharmacie"),
("Où est la médiathèque par rapport au parc ?","En face","Derrière","Dans le parc","en face du parc"),
("Où est l’arrêt de bus ?","Devant la porte","Derrière le café","Dans la gare","devant la porte")],
[("Passant","Excusez-moi, la médiathèque est loin ?"),("Habitante","Non, à environ cinq minutes à pied."),("Passant","Je tourne avant ou après la pharmacie ?"),("Habitante","Après la pharmacie, à gauche."),("Passant","Et l’entrée est près du café ?"),("Habitante","Oui, juste à côté. Vous verrez le bâtiment blanc.")],
[("Combien de temps faut-il à pied ?","Environ cinq minutes","Une demi-heure","Une heure","cinq minutes à pied"),
("De quel côté faut-il tourner ?","À gauche","À droite","Il ne faut pas tourner","à gauche")],
[("tout droit","straight ahead"),("en face du parc","opposite the park"),("à côté du café","next to the café")],
"Give written directions from a station to a place you invent. Include three landmarks and two movement instructions.",
"Ask for directions, repeat the route to check your understanding, and ask one clarification question.",
"Place phrases identify locations; they are not automatically direct objects. À + le becomes au and de + le becomes du. Keep de la and à la separate."),

P(12,"De nouvelles habitudes", """Depuis un mois, Karim organise mieux ses soirées. Il ne travaille plus après vingt heures. Il lit souvent quelques pages avant de dormir et ne regarde presque jamais son téléphone au lit. Le mercredi, il joue au football avec ses voisins. Il n’aime pas courir seul. Le dimanche, il ne prévoit rien le matin : il se repose. Ses habitudes changent peu à peu, sans programme compliqué.""",
"Karim explains changes to his routine, including frequency and negation.",[
("Quand arrête-t-il de travailler ?","À vingt heures au plus tard","À minuit","Il ne s’arrête jamais","ne travaille plus après vingt heures"),
("Avec qui joue-t-il au football ?","Ses voisins","Ses collègues","Son frère","avec ses voisins"),
("Que fait-il le dimanche matin ?","Il se repose","Il travaille","Il court seul","il se repose")],
[("Voisine","Tu viens courir samedi matin ?"),("Karim","Non, je ne cours pas seul, mais je peux venir avec toi."),("Voisine","Très bien. À huit heures ?"),("Karim","Pas si tôt. Je ne me lève jamais avant neuf heures le samedi."),("Voisine","Alors, rendez-vous à dix heures."),("Karim","D’accord, dix heures me convient.")],
[("Pourquoi refuse-t-il huit heures ?","Il se lève après neuf heures le samedi","Il travaille à huit heures","Il ne veut voir personne","jamais avant neuf heures"),
("Quelle heure est finalement choisie ?","Dix heures","Huit heures","Neuf heures","rendez-vous à dix heures")],
[("ne travaille plus","no longer works"),("presque jamais","almost never"),("peu à peu","little by little")],
"Describe three habits and two things you do not do. Distinguish pas, jamais and plus.",
"Compare routines with a partner. Agree on an activity time that suits both people and explain one constraint.",
"Place ne/n’ before the finite verb and pas, jamais or plus after it in standard written French. In a compound tense the main negation surrounds the auxiliary. Do not automatically add pas to jamais."),
]
